import{_ as t,o as n,c as a,ah as i}from"./chunks/framework.DDXs_i7t.js";const p=JSON.parse('{"title":"Milestone: The Horten Mystery goes international!","description":"A historic moment for the project – the website is now available in two languages (German/English).","frontmatter":{"title":"Milestone: The Horten Mystery goes international!","description":"A historic moment for the project – the website is now available in two languages (German/English).","date":"2026-02-27T00:00:00.000Z"},"headers":[],"relativePath":"en/logbuch/2026-02-27-international-version.md","filePath":"en/logbuch/2026-02-27-international-version.md"}'),o={name:"en/logbuch/2026-02-27-international-version.md"};function s(r,e,l,h,c,d){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="milestone-the-horten-mystery-goes-international" tabindex="-1">Milestone: The Horten Mystery goes international! <a class="header-anchor" href="#milestone-the-horten-mystery-goes-international" aria-label="Permalink to &quot;Milestone: The Horten Mystery goes international!&quot;">​</a></h1><p style="color:red;font-size:1.5rem;font-weight:bold;text-align:center;border:2px solid red;padding:20px;border-radius:10px;margin:20px 0;"> 🔥 A HISTORIC STEP: THE PROJECT IS NOW BILINGUAL! 🔥 </p><p>Today we have achieved a decisive breakthrough. To make the machinations surrounding the legacy of Helmut and Heidi Horten, as well as the intertwinings in Austrian politics, accessible to a worldwide audience, we have switched the entire infrastructure of the website to <strong>multilingualism (i18n)</strong>.</p><p><strong>What this means:</strong></p><ul><li>A new language switcher (globe icon) allows seamless switching between German and English.</li><li>The core sections (concept, cast, pointillism) have already been fully translated.</li><li>We are now systematically starting to translate the extensive research data and the 40-page screenplay.</li></ul><p>This step is essential to make the &quot;Pointillism of Capital&quot; visible beyond Austria&#39;s borders. Corruption and the processing of Nazi-looted capital are global issues that require a global language.</p><p><em>Documented by Volti Sodala &amp; Gemini CLI. February 2026.</em></p>',7)])])}const m=t(o,[["render",s]]);export{p as __pageData,m as default};
